<script setup>
import { Head, Link, router, usePage } from '@inertiajs/vue3';
import { ref } from 'vue';
import AdminLayout from '../../../layouts/AdminLayout.vue';
const props = defineProps({ archives: Object, search: String });
const query = ref(props.search); const restoring = ref(false);
function restore(item) { if (!confirm(`Kembalikan level ${item.level_name || 'tanpa nama'} ke draf program?`)) return; restoring.value = true; router.post(`/admin/system/archives/${item.program_id}/restore`, { revision: item.revision, subprogram_id: item.subprogram_id, level_id: item.level_id }, { preserveScroll: true, onFinish: () => restoring.value = false }); }
</script>
<template><Head title="Arsip Level" /><AdminLayout><h1 class="text-2xl font-semibold">Arsip Level</h1><p class="mt-2 text-sm text-muted">Level yang dikeluarkan dari daftar aktif. Materinya tetap tersimpan.</p><p v-if="usePage().props.flash?.success" role="status" class="mt-5 rounded-lg bg-brand-soft p-4 text-sm">{{ usePage().props.flash.success }}</p><p v-for="(error, key) in usePage().props.errors" :key="key" role="alert" class="field-error">{{ error }}</p><form class="my-6 flex max-w-lg gap-3" @submit.prevent="router.get('/admin/system/archives', { search: query })"><input v-model="query" class="admin-input" aria-label="Cari program atau level" placeholder="Cari program atau level" /><button class="admin-secondary">Cari</button></form><section class="learning-panel"><div class="overflow-x-auto"><table class="w-full min-w-[620px] text-left text-sm"><thead class="bg-page text-xs text-muted"><tr><th class="p-4">Program</th><th class="p-4">Subprogram</th><th class="p-4">Level</th><th class="p-4">Paket</th><th class="p-4">Tindakan</th></tr></thead><tbody class="divide-y divide-line"><tr v-for="item in archives.data" :key="item.level_id"><td class="p-4">{{ item.program_name || 'Tanpa nama' }}</td><td class="p-4">{{ item.subprogram_name || 'Tanpa nama' }}</td><td class="p-4">{{ item.level_name || 'Tanpa nama' }}</td><td class="p-4">{{ item.packages }}</td><td class="p-4"><button class="admin-secondary" :disabled="restoring" @click="restore(item)">Kembalikan</button></td></tr><tr v-if="!archives.data.length"><td colspan="5" class="p-12 text-center text-muted">Tidak ada level dalam arsip.</td></tr></tbody></table></div><nav class="flex justify-between border-t border-line p-4 text-xs"><Link v-if="archives.prev_page_url" :href="archives.prev_page_url">Sebelumnya</Link><span>{{ archives.current_page }} / {{ archives.last_page }}</span><Link v-if="archives.next_page_url" :href="archives.next_page_url">Berikutnya</Link></nav></section></AdminLayout></template>
